  ('gs-satt-board-cumilla-2020-mcq-027', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p59', 'পলির এরূপ পরিবর্তনের জন্য দায়ী— i. ইস্ট্রোজেন ii. প্রজেস্টেরন iii. টেস্টোস্টেরন নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'gs-satt-board-cumilla-2020-mcq', false, 'board-mcq', null, 'পলি সপ্তম শ্রেণির ছাত্রী। ইদানিং সে অধিকাংশ সময় আয়নার সামনে একাকী বসে থাকে। তার কথাবার্তায় ও আচরণে পরিবর্তন পরিলক্ষিত হচ্ছে। তাছাড়া সে এখন পরিপাটি থাকতে ভালোবাসে।', 'cumilla', 2020, true),
  ('gs-satt-board-cumilla-2020-mcq-028', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p59', 'পলির এ বয়সে আর কী দৈহিক পরিবর্তন হতে পারে?', 'mcq', '{"ক":"বুক ও কাঁধ চওড়া হওয়া","খ":"গলার স্বর মোটা হওয়া","গ":"কোমরের হাড় মোটা হওয়া","ঘ":"স্বর ভঙ্গ হওয়া"}'::jsonb, 'গ', 1, false, 'gs-satt-board-cumilla-2020-mcq', false, 'board-mcq', null, 'পলি সপ্তম শ্রেণির ছাত্রী। ইদানিং সে অধিকাংশ সময় আয়নার সামনে একাকী বসে থাকে। তার কথাবার্তায় ও আচরণে পরিবর্তন পরিলক্ষিত হচ্ছে। তাছাড়া সে এখন পরিপাটি থাকতে ভালোবাসে।', 'cumilla', 2020, true),
