  ('gs-satt-board-dhaka-2024-mcq-030', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p37', 'এনামুলের বাসায় ৬০ ওয়াটের ৬ টি বাল্ব দৈনিক ৬ ঘণ্টা করে চলে। প্রতি ইউনিট বিদ্যুৎ খরচ ৬ টাকা করে হলে ৬ দিনে এনামুলের বাসায় বিদ্যুৎ বিল কত টাকা হবে?', 'mcq', '{"ক":"১২-৯৬","খ":"৬৪.৮","গ":"৭৭.৭৬","ঘ":"৩৮৮.৮"}'::jsonb, 'গ', 1, false, 'gs-satt-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
