  ('gs-satt-board-dhaka-2025-mcq-002', 'class9-10-general-science-bn-guide', 'satt-gs-board-2025.pdf p19', 'উদ্দীপকের যৌগটি দূষিত হলে- i. মানুষের টাইফয়েড, কলেরা, আমাশয় রোগ সৃষ্টি করতে পারে ii. মানুষের মস্তিষ্ক বিকল হতে পারে iii. জীবদেহে স্বাশপ্রশ্বাসজনিত রোগ সৃষ্টি হতে পারে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, null, 1, false, 'gs-satt-board-dhaka-2025-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই | উদ্দীপক ছবি আকারে (ছাপায় লেখা নেই)', null, 'dhaka', 2025, true),
  ('gs-satt-board-dhaka-2025-mcq-003', 'class9-10-general-science-bn-guide', 'satt-gs-board-2025.pdf p19', 'সিয়ামের BMI কত?', 'mcq', '{"ক":"১৭.৩","খ":"২৯.৪","গ":"৫২.৮৯","ঘ":"৮৫"}'::jsonb, null, 1, false, 'gs-satt-board-dhaka-2025-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই', 'সিয়ামের ওজন ৫০ কেজি এবং উচ্চতা ১.৭ মিটার। সে বিরানি, পোলাও, তেহারি খেতে বেশি পছন্দ করে। শাক-সবজি ও ফলমূল খুব কম খায়।', 'dhaka', 2025, true),
  ('gs-satt-board-dhaka-2025-mcq-004', 'class9-10-general-science-bn-guide', 'satt-gs-board-2025.pdf p20', 'সিয়ামের যে সকল স্বাস্থ্যগত সমস্যা হতে পারে- i. শরীরে অতিরিক্ত চর্বি জমতে পারে ii. খাদ্য পরিপাকে ব্যাঘাত ঘটতে পারে iii. দেহে ভিটামিন ও খনিজ লবণের অভাবজনিত রোগ হতে পারে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, null, 1, false, 'gs-satt-board-dhaka-2025-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই', 'সিয়ামের ওজন ৫০ কেজি এবং উচ্চতা ১.৭ মিটার। সে বিরানি, পোলাও, তেহারি খেতে বেশি পছন্দ করে। শাক-সবজি ও ফলমূল খুব কম খায়।', 'dhaka', 2025, true),
  ('gs-satt-board-dhaka-2025-mcq-005', 'class9-10-general-science-bn-guide', 'satt-gs-board-2025.pdf p20', 'বর্তনীটির ক্ষেত্রে- i. এটি সমান্তরাল বর্তনী ii. প্রতিটি বাতি সমান ভোল্টেজ পাবে iii. একটি বাতি নষ্ট হলে অন্য বাতিগুলো জ্বলবে না নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, null, 1, false, 'gs-satt-board-dhaka-2025-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই | উদ্দীপক ছবি আকারে (ছাপায় লেখা নেই)', null, 'dhaka', 2025, true),
